package com.gpcbellary.cms.controller; import com.gpcbellary.cms.model.Company; import com.gpcbellary.cms.repository.CompanyRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/companies") @CrossOrigin public class CompanyController{private final CompanyRepository repo; public CompanyController(CompanyRepository repo){this.repo=repo;} @GetMapping public List<Company> all(){return repo.findAll();} @PostMapping public Company create(@RequestBody Company x){return repo.save(x);} @PutMapping("/{id}") public Company update(@PathVariable Long id,@RequestBody Company x){x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
